package main

// hashcatCryptModeVector keeps the source mode separate from selfTestVector's
// canonical type name. The self-test catalogue requires canonical names, while
// the mode lets focused tests exercise every numeric compatibility alias.
type hashcatCryptModeVector struct {
	mode   string
	vector selfTestVector
}

